  for(i=1;i<=length($0);i++) {
    c=substr($0,i,1)
    if(c=="F") fc++
    else if(c=="A") ac++
    else if(c=="C") cc++
    else if(c=="G") gc++
    else if(c=="T") tc++
  }
} END {
  print "A:",ac,"C:",cc,"G:",gc,"T:",tc,"F:",fc
}'

