summary:
bash: # Check for cycles - follow a path from a node
# Let's trace from ATAGCCAGTGCCTGATACT (FG = no forward, no backward)
# Forward extension F means no forward extension
# So this is a start node? Let's check what k-mer extends to it
awk -F'\t' '{
  kmer=$1; ext=$2
  # Forward extension of this kmer is ext[0]
  # The kmer that extends forward from this one would have prefix = kmer[1:] + ext[0]
  fwd=substr(ext,1,1)
  if(fwd!="F") {
    next_kmer = substr(kmer,2) fwd
    print "Forward from " kmer " (" fwd "): " next_kmer
  }
  bwd=substr(ext,2,1)
  if(bwd!="F") {
    prev_kmer = bwd substr(kmer,1,18)
    print "Backward from " kmer " (" bwd "): " prev_kmer
  }
}' /app/test | head -20

